const enrolments = [
  { student: 'Asha', course: 'MEAN', fee: 25000, active: true, aadhaar: 'XXXX' },
  { student: 'Ravi', course: 'MEAN', active: true, aadhaar: 'YYYY' },
  { student: 'Meera', course: 'Java', fee: 18000, active: false, aadhaar: 'ZZZZ' },
];

const safe = enrolments
  .filter(e => e.active)
  .map(({ aadhaar, fee = 0, ...rest }) => ({ ...rest, fee }));

const total = safe.reduce((sum, { fee }) => sum + fee, 0);
const byCourse = Object.groupBy(safe, e => e.course);

console.log(safe.length, total, Object.keys(byCourse)); // 2 25000 [ 'MEAN' ]

