const records = JSON.parse(stdin);
if (records.length === 0) {
  console.log('no records');
} else {
  const normalised = records.map(({ name, course = 'Unassigned', score = 0 }) => ({ name, course, score }));
  const groups = normalised.reduce((acc, r) => {
    (acc[r.course] ||= []).push(r);
    return acc;
  }, {});
  const courses = Object.keys(groups).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const course of courses) {
    const list = groups[course];
    const total = list.reduce((sum, { score }) => sum + score, 0);
    const top = list.reduce((best, r) =>
      r.score > best.score || (r.score === best.score && r.name < best.name) ? r : best
    );
    console.log(course + ': count=' + list.length + ' avg=' + (total / list.length).toFixed(1) + ' top=' + top.name);
  }
}

